final class AudioSignal {
    let name: String
    let rate: Int
    let samples: [Int]
    let origin: String
    let ingredients: [AudioSignal]
    init(_ name: String, _ rate: Int, _ samples: [Int], _ origin: String = "input", _ ingredients: [AudioSignal] = []) { self.name = name; self.rate = rate; self.samples = samples; self.origin = origin; self.ingredients = ingredients }
}
        signals[destination] = AudioSignal(destination, rate, samples, "line \(line) \(name)", arguments.sources)
    func trace(_ source: AudioSignal, _ depth: Int) -> [String] { [String(repeating: "  ", count: depth) + "\(source.name) <- \(source.origin)"] + source.ingredients.flatMap { trace($0, depth + 1) } }
        case "TRACE": return [source.name] + trace(source, 1)
